import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor depthwise_conv_h(torch::Tensor x, torch::Tensor weight,
                                c10::optional<torch::Tensor> bias_opt,
                                int64_t strideH, int64_t strideW,
                                int64_t padH, int64_t padW,
                                int64_t dilH);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#define TILE_H 16
#define TILE_W 16
#define ROWS_PER_THREAD 4
#define COLS_PER_THREAD 4

__global__ void depthwise_conv_h_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int Hout, int Wout,
    int kH,
    int sH, int sW,
    int pH, int pW,
    int dH,
    int SH_H, int SH_W)
{
    extern __shared__ __align__(16) float smem_raw[];

    int nc = blockIdx.x;
    int batch = nc / C;
    int channel = nc % C;

    int h_tile_start = blockIdx.y * (TILE_H * ROWS_PER_THREAD);
    int w_tile_start = blockIdx.z * TILE_W;

    int tx = threadIdx.x; // width
    int ty = threadIdx.y; // height

    size_t in_offset  = (size_t)(batch * C + channel) * (size_t)H * (size_t)W;
    size_t out_offset = (size_t)(batch * C + channel) * (size_t)Hout * (size_t)Wout;

    Tensor gIn  = make_tensor(make_gmem_ptr(input + in_offset),
                               make_shape(H, W), make_stride(W, 1));
    Tensor gOut = make_tensor(make_gmem_ptr(output + out_offset),
                               make_shape(Hout, Wout), make_stride(Wout, 1));
    Tensor sIn  = make_tensor(make_smem_ptr(smem_raw),
                               make_shape(SH_H, SH_W), make_stride(SH_W, 1));

    int base_h = h_tile_start * sH - pH;
    int base_w = w_tile_start * sW - pW;

    int tid = ty * blockDim.x + tx;
    int nthreads = blockDim.x * blockDim.y;
    int total_smem = SH_H * SH_W;
    // The shared-memory tile is loaded from a *contiguous* window of the
    // input row (gw = base_w + sw, incrementing by 1 regardless of stride),
    // so we can safely vectorize this copy with float4 loads whenever the
    // row width is a multiple of 4 and the resulting global address is
    // 16-byte aligned, falling back to scalar loads otherwise.
    if ((SH_W & 3) == 0) {
        int total_vec = total_smem >> 2;
        for (int vidx = tid; vidx < total_vec; vidx += nthreads) {
            int idx4 = vidx * 4;
            int sh = idx4 / SH_W;
            int sw0 = idx4 % SH_W;
            int gh = base_h + sh;
            int gw0 = base_w + sw0;
            float4 val4 = make_float4(0.f, 0.f, 0.f, 0.f);
            if (gh >= 0 && gh < H) {
                const float* gptr = input + in_offset + (size_t)gh * (size_t)W + (size_t)gw0;
                bool aligned = ((reinterpret_cast<uintptr_t>(gptr) & 0xF) == 0);
                if (aligned && gw0 >= 0 && (gw0 + 3) < W) {
                    val4 = *reinterpret_cast<const float4*>(gptr);
                } else {
                    float tmp[4];
                    #pragma unroll
                    for (int k = 0; k < 4; ++k) {
                        int gw = gw0 + k;
                        tmp[k] = (gw >= 0 && gw < W) ? input[in_offset + (size_t)gh * (size_t)W + (size_t)gw] : 0.f;
                    }
                    val4 = make_float4(tmp[0], tmp[1], tmp[2], tmp[3]);
                }
            }
            float4* sptr = reinterpret_cast<float4*>(&smem_raw[sh * SH_W + sw0]);
            *sptr = val4;
        }
    } else {
        for (int idx = tid; idx < total_smem; idx += nthreads) {
            int sh = idx / SH_W;
            int sw = idx % SH_W;
            int gh = base_h + sh;
            int gw = base_w + sw;
            float val = 0.f;
            if (gh >= 0 && gh < H && gw >= 0 && gw < W) {
                val = gIn(gh, gw);
            }
            sIn(sh, sw) = val;
        }
    }
    __syncthreads();

    int w_out_base = w_tile_start + tx * COLS_PER_THREAD;
    int sw_base = tx * COLS_PER_THREAD * sW;
    #pragma unroll
    for (int r = 0; r < ROWS_PER_THREAD; ++r) {
        int h_out = h_tile_start + ty + r * TILE_H;
        if (h_out < Hout) {
            float acc[COLS_PER_THREAD];
            #pragma unroll
            for (int c = 0; c < COLS_PER_THREAD; ++c) acc[c] = 0.f;
            int sh_base = (ty + r * TILE_H) * sH;
            #pragma unroll
            for (int kh = 0; kh < kH; ++kh) {
                int sh = sh_base + kh * dH;
                float wv = weight[channel * kH + kh];
                #pragma unroll
                for (int c = 0; c < COLS_PER_THREAD; ++c) {
                    int sw = sw_base + c * sW;
                    acc[c] += sIn(sh, sw) * wv;
                }
            }
            if (bias != nullptr) {
                #pragma unroll
                for (int c = 0; c < COLS_PER_THREAD; ++c) acc[c] += bias[channel];
            }
            if (sW == 1 && (w_out_base + COLS_PER_THREAD) <= Wout) {
                float* optr = &output[out_offset + (size_t)h_out * (size_t)Wout + (size_t)w_out_base];
                bool aligned = ((reinterpret_cast<uintptr_t>(optr) & 0xF) == 0);
                if (aligned) {
                    float4 outv = make_float4(acc[0], acc[1], acc[2], acc[3]);
                    *reinterpret_cast<float4*>(optr) = outv;
                } else {
                    #pragma unroll
                    for (int c = 0; c < COLS_PER_THREAD; ++c) {
                        optr[c] = acc[c];
                    }
                }
            } else {
                #pragma unroll
                for (int c = 0; c < COLS_PER_THREAD; ++c) {
                    int w_out = w_out_base + c;
                    if (w_out < Wout) {
                        output[out_offset + (size_t)h_out * (size_t)Wout + (size_t)w_out] = acc[c];
                    }
                }
            }
        }
    }
}

torch::Tensor depthwise_conv_h(torch::Tensor x, torch::Tensor weight,
                                c10::optional<torch::Tensor> bias_opt,
                                int64_t strideH, int64_t strideW,
                                int64_t padH, int64_t padW,
                                int64_t dilH) {
    TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N,C,H,W)");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "Only float32 supported");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();

    int N = (int)x_c.size(0);
    int C = (int)x_c.size(1);
    int H = (int)x_c.size(2);
    int W = (int)x_c.size(3);

    int kH = (int)w_c.size(2); // weight shape (C,1,kH,1)

    int sH = (int)strideH;
    int sW = (int)strideW;
    int pH = (int)padH;
    int pW = (int)padW;
    int dH = (int)dilH;

    int Hout = (H + 2 * pH - dH * (kH - 1) - 1) / sH + 1;
    int Wout = (W + 2 * pW - 1) / sW + 1;

    auto output = torch::empty({N, C, Hout, Wout}, x_c.options());

    const float* bias_ptr = nullptr;
    torch::Tensor bias_c;
    if (bias_opt.has_value() && bias_opt.value().defined()) {
        bias_c = bias_opt.value().contiguous();
        bias_ptr = bias_c.data_ptr<float>();
    }

    int SH_H = (TILE_H * ROWS_PER_THREAD - 1) * sH + (kH - 1) * dH + 1;
    int SH_W = (TILE_W - 1) * sW + 1;

    dim3 block(TILE_W / COLS_PER_THREAD, TILE_H);
    dim3 grid((unsigned)(N * C),
               (unsigned)((Hout + (TILE_H * ROWS_PER_THREAD) - 1) / (TILE_H * ROWS_PER_THREAD)),
               (unsigned)((Wout + TILE_W - 1) / TILE_W));

    size_t smem_bytes = (size_t)SH_H * (size_t)SH_W * sizeof(float);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    depthwise_conv_h_kernel<<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C, H, W,
        Hout, Wout,
        kH,
        sH, sW,
        pH, pW,
        dH,
        SH_H, SH_W);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "depthwise_conv_h launch failed");
    return output;
}
"""

cute_ext = load_inline(
    name="cute_depthwise_conv_h_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["depthwise_conv_h"],
    extra_cflags=["-O3", "-I/workspace/cutegen_test/cutegen/cutlass/include"],
    extra_cuda_cflags=["-O3", "-I/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a depthwise 2D convolution with a square input and an asymmetric kernel
    (kernel_size, 1), implemented with a custom CUTe/CUDA kernel.
    """
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1,
                 padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv2d = nn.Conv2d(in_channels, in_channels, kernel_size=(kernel_size, 1),
                                 stride=stride, padding=padding, dilation=dilation,
                                 groups=in_channels, bias=bias)
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv2d.weight
        bias = self.conv2d.bias

        sH, sW = self.conv2d.stride
        pH, pW = self.conv2d.padding
        dH, _ = self.conv2d.dilation

        x_in = x.contiguous().float() if x.dtype != torch.float32 else x.contiguous()

        out = self._ext.depthwise_conv_h(
            x_in, weight, bias,
            int(sH), int(sW),
            int(pH), int(pW),
            int(dH),
        )
        return out

